import json,pathlib,html,os,shutil
from urllib.parse import urlparse
r=pathlib.Path(__file__).resolve().parent;out=r/'dist';out.mkdir(exist_ok=True)
allp=json.loads((r/'data/products.json').read_text());assert len({p['id'] for p in allp})==len(allp)
products=[p for p in allp if p['publication_status']=='published']
for p in products:
 assert p['concentration'] and p['facts']['notes'] and urlparse(p['official_url']).scheme=='https'
 assert any(s['type']=='official' and s['status']=='verified' for s in p['sources'])
base=os.getenv('SITE_URL','https://scent-atlas-preview.vercel.app').rstrip('/');e=html.escape
css='''body{margin:0;background:#f6f4ed;color:#292e29;font:15px/1.8 system-ui}header,main,footer{max-width:1180px;margin:auto;padding:28px}header{display:flex;justify-content:space-between;border-bottom:1px solid #d7d9cc}a{color:inherit}nav a{margin-left:20px}h1{font:normal clamp(36px,6vw,72px)/1.2 Georgia,serif;margin:40px 0 24px}h2{font-weight:400}.hero{padding:28px 0 50px}.eyebrow{letter-spacing:.18em;color:#67715d;font-size:12px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.card{border-top:1px solid #c9cdbf;padding:22px 0}.visual{height:180px;background:#ebece2;display:grid;place-items:center;font:46px Georgia;color:#777e68}.muted,small{color:#68705e}.filters{display:flex;gap:12px;flex-wrap:wrap;padding:20px 0}input,select,button{font:inherit;padding:9px 12px;border:1px solid #c9cdbf;background:#fffdf6;color:inherit;border-radius:2px}button{cursor:pointer}.tag{font-size:12px;margin:4px 4px 0 0;padding:3px 8px;background:#e8ebdf}.texture{background:#f0e7db}.mood{background:#e7e7ef}.note{padding:20px;border-left:2px solid #68705e;background:#eeeee5}.dictionary{display:grid;grid-template-columns:1fr 1fr;gap:32px}details{border-top:1px solid #ddd;padding:18px 0}footer{border-top:1px solid #ccc}article h2{font:26px Georgia}a:focus-visible,button:focus-visible{outline:3px solid #6f805c}@media(max-width:700px){main,header,footer{padding:20px}.grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.visual{height:140px}.dictionary{grid-template-columns:1fr}nav a{margin-left:10px}.filters>*{max-width:100%;min-width:0}article h2{font-size:20px}}'''
(out/'style.css').write_text(css)
def page(title,desc,body,path=''):
 canonical=f'<link rel="canonical" href="{e(base+"/"+path)}">' if base else ''
 return f'<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} | KAORINK</title><meta name="description" content="{e(desc)}"><meta property="og:title" content="{e(title)} | KAORINK"><meta property="og:description" content="{e(desc)}"><meta property="og:type" content="website">{canonical}<link rel="stylesheet" href="/style.css"></head><body><header><a href="/" style="text-decoration:none;letter-spacing:.16em">KAORINK</a><nav><a href="/#library">図鑑</a><a href="/#scenes">シーン</a><a href="/#dictionary">用語集</a></nav></header><main>{body}</main><footer>KAORINK — 香りを知る。香りとつながる。<br><small>公式情報とAIの解釈を分けて紹介しています。実使用レビューではありません。</small></footer></body></html>'
def visual(p):
 im=p['image']
 if im.get('url') and im.get('rights')!='unconfirmed':
  return f'<figure><img src="{e(im["url"])}" alt="{e(p["brand"]+" "+p["name"])}" loading="lazy" style="width:100%;height:220px;object-fit:contain"><figcaption><small>{e(im.get("caption",""))}<br>Photo: <a href="{e(im["source"])}">{e(im["author"])}</a> / <a href="{e(im["license_url"])}">{e(im["rights"])}</a>（画像変更なし）</small></figcaption></figure>'
 return '<div class="visual"><small>商品写真を確認中</small></div>'
def card(p):
 i=p['inference'];tags=''.join(f'<button class="tag {k}" data-key="{k}" data-value="{e(v)}">{e(v)}</button>' for k,vals in [('family',[i['family']]),('texture',i['texture']),('mood',i['mood'])] for v in vals)
 return f'<article class="card" data-id="{p["id"]}">{visual(p)}<small>{e(p["brand"])}</small><h2><a href="/perfumes/{p["id"]}/">{e(p["name"])}</a></h2><p>{e(p["name_ja"] or "")} · {e(p["concentration"])}</p><p>{e(i["description"])}</p><small>香りの印象：AI推定</small><div>{tags}</div><a href="{e(p["official_url"])}" target="_blank" rel="noopener noreferrer">公式商品ページ ↗</a></article>'
for p in products:
 d=out/'perfumes'/p['id'];d.mkdir(parents=True,exist_ok=True);i=p['inference'];body=f'<p class="eyebrow">{e(p["brand"])} / {e(p["concentration"])}</p><h1>{e(p["name"])}</h1>{visual(p)}<p>{e(p["name_ja"] or "")}</p><h2>公式に紹介されているノート</h2><p>{e("・".join(p["facts"]["notes"]))}</p><p class="muted">ノートは香りの表現であり、実際の配合成分を保証するものではありません。</p><h2>香りのイメージ</h2><p>{e(i["description"])}</p><p class="note">AIによる推定です。実際に試香した評価ではありません。</p><h2>使用シーンの提案</h2><p>{e("・".join(i["scenes"])) or "検討中"}</p><h2>情報の出典</h2><a href="{e(p["official_url"])}">{e(p["brand"])} 公式商品ページ</a><p>確認日：2026年10月27日。価格・在庫・写真の転載権は未確認のため掲載していません。</p>'
 (d/'index.html').write_text(page(p['name'],i['description'],body,'perfumes/'+p['id']+'/'))
filters='<input id="q" aria-label="ブランド・商品名で検索" placeholder="ブランド・商品名で検索">'
for key,label in [('brand','ブランド'),('family','香調'),('texture','質感'),('mood','印象'),('scenes','シーン'),('seasons','季節'),('times','時間帯')]:
 vals=sorted({v for p in products for v in ([p['brand']] if key=='brand' else ([p['inference'][key]] if key=='family' else p['inference'][key]))})
 filters+=f'<select id="{key}" aria-label="{label}"><option value="">すべての{label}</option>'+''.join(f'<option>{e(v)}</option>' for v in vals)+'</select>'
scenehtml=''
for s in json.loads((r/'data/scenes.json').read_text()):
 items=[p for p in products if p['name'] in s[1:]]
 scenehtml+=f'<details><summary>{e(s[0])}</summary><p>AIによるシーン提案</p>'+(''.join(f'<p><a href="/perfumes/{p["id"]}/">{e(p["name"])}</a></p>' for p in items) or '<p>掲載候補を確認中です。</p>')+'</details>'
gloss=''.join('<section><h3>'+e(g[0])+'</h3><dl>'+''.join(f'<dt>{e(t[0])}</dt><dd>{e(t[1])}</dd>' for t in g[1])+'</dl></section>' for g in json.loads((r/'data/glossary.json').read_text()))
body=f'<section class="hero"><p class="eyebrow">THE FRAGRANCE LIBRARY</p><h1>香りを知る。<br>香りとつながる。</h1><p>名前から、ノートから、過ごしたい時間から。<br>自分に合う一本を探す、香りの図鑑。</p></section><section id="library"><h2>Fragrance Library</h2><p>{len(products)}件公開 / {len(allp)-len(products)}件確認待ち</p><div class="filters">{filters}<button id="reset">条件を解除</button></div><p id="selected" aria-live="polite"></p><p id="count" aria-live="polite"></p><div class="grid">'+''.join(card(p) for p in products)+f'</div><p id="empty" hidden>条件に一致する香水がありません。</p></section><section id="scenes"><h2>Scene Selection</h2>{scenehtml}</section><section id="dictionary"><h2>Scent Dictionary</h2><div class="dictionary">{gloss}</div></section><script src="/app.js" defer></script>'
(out/'index.html').write_text(page('香りを知る。香りとつながる。','公式情報とAIの解釈から香水を探せるフレグランス図鑑。',body))
(out/'catalog.json').write_text(json.dumps([{k:v for k,v in p.items() if k!='legacy'} for p in products],ensure_ascii=False))
(out/'app.js').write_text('''fetch('/catalog.json').then(r=>r.json()).then(data=>{const keys=['brand','family','texture','mood','scenes','seasons','times'],q=document.getElementById('q'),get=k=>document.getElementById(k);function render(){let n=0;const active=keys.filter(k=>get(k).value);data.forEach(p=>{let match=[p.brand,p.name,p.name_ja].join(' ').toLowerCase().includes(q.value.toLowerCase())&&active.every(k=>{let v=k==='brand'?p.brand:p.inference[k];return Array.isArray(v)?v.includes(get(k).value):v===get(k).value});document.querySelector('[data-id="'+p.id+'"]').hidden=!match;if(match)n++});get('count').textContent=n+'件';get('empty').hidden=n!==0;get('selected').textContent=active.map(k=>get(k).value).join(' / ')}keys.forEach(k=>get(k).addEventListener('change',render));q.addEventListener('input',render);get('reset').onclick=()=>{keys.forEach(k=>get(k).value='');q.value='';render()};document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{get(b.dataset.key).value=b.dataset.value;render();get('library').scrollIntoView({behavior:'smooth'})});render()}).catch(()=>document.getElementById('count').textContent='絞り込みを読み込めませんでした。再読み込みしてください。');''')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\n'+('Sitemap: '+base+'/sitemap.xml\n' if base else ''))
urls=['']+['perfumes/'+p['id']+'/' for p in products]
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+(''.join('<url><loc>'+e(base+'/'+u)+'</loc></url>' for u in urls) if base else '')+'</urlset>')
print(f'Validated {len(allp)} records; generated {len(products)} published details. Canonical configured: {bool(base)}')
